
# ------------------------------------------------------------------------------
# 3b. DESCRIZIONI DELLE VOCI E ALTRE LINGUE
# ------------------------------------------------------------------------------
# Le descrizioni compaiono passando con il mouse su una voce: dicono cosa fa
# e cosa si guadagna, senza entrare nel come. Le lingue oltre a italiano e
# inglese stanno qui; una chiave mancante ripiega sull'inglese.
$script:Tips = @{
    chkMMCSS = @{ it = "Dà la precedenza a giochi e audio quando il computer è sotto carico. Meno scatti e audio più pulito."; en = "Gives games and audio priority when the computer is under load. Fewer stutters and cleaner audio." }
    chkPriority = @{ it = "Riserva più tempo del processore alla finestra che stai usando. Il programma in primo piano risponde più in fretta."; en = "Gives more processor time to the window you are using. The foreground program responds faster." }
    chkKernelMem = @{ it = "Tiene in memoria le parti centrali di Windows invece di spostarle su disco. Sistema più reattivo con molta RAM."; en = "Keeps the core of Windows in memory instead of moving it to disk. A snappier system when you have plenty of RAM." }
    chkKernelDpc = @{ it = "Riduce i ritardi nella gestione di schede e periferiche. Utile contro micro-scatti e crepitii audio."; en = "Reduces delays in handling cards and devices. Helps against micro-stutter and audio crackles." }
    chkTimer = @{ it = "Fa scattare i timer di sistema con più precisione. Tempi di risposta più regolari nei giochi."; en = "Makes system timers fire more precisely. More consistent response times in games." }
    chkPowerThrottling = @{ it = "Impedisce a Windows di rallentare i programmi in background per risparmiare energia. Prestazioni costanti, consumi un po' più alti."; en = "Stops Windows from slowing down background programs to save power. Steady performance, slightly higher power draw." }
    chkUSBSuspend = @{ it = "Tiene sempre attive le porte USB. Evita mouse, tastiere e schede audio che si scollegano o rispondono in ritardo."; en = "Keeps USB ports always active. Prevents mice, keyboards and audio interfaces from dropping out or lagging." }
    chkNtfsPerf = @{ it = "Il disco smette di annotare ogni lettura di file e usa più memoria per i dati di sistema. Meno scritture e accessi più veloci."; en = "The disk stops recording every file read and uses more memory for system data. Fewer writes and faster access." }
    chkRamTweak = @{ it = "Raggruppa i servizi di Windows in funzione della RAM installata. Meno processi aperti e memoria usata meglio."; en = "Groups Windows services according to the installed RAM. Fewer running processes and better memory use." }
    chkGameMode = @{ it = "Attiva la Modalità gioco: Windows mette in secondo piano aggiornamenti e attività mentre giochi."; en = "Turns on Game Mode: Windows holds back updates and background work while you play." }
    chkFSO = @{ it = "Fa girare i giochi a schermo intero in modo esclusivo. Può ridurre la latenza di input in alcuni titoli."; en = "Runs full-screen games in true exclusive mode. Can reduce input latency in some titles." }
    chkGameDVR = @{ it = "Spegne la registrazione in background della Xbox Game Bar. Libera risorse e fa guadagnare qualche fotogramma."; en = "Turns off Xbox Game Bar background recording. Frees resources and gains a few frames." }
    chkHAGS = @{ it = "Lascia che la scheda video gestisca da sola la propria memoria. Latenza più bassa sulle schede recenti."; en = "Lets the graphics card manage its own memory. Lower latency on recent cards." }
    chkVisualFX = @{ it = "Riduce animazioni ed effetti grafici di Windows. Interfaccia più scattante sui PC meno potenti."; en = "Reduces Windows animations and visual effects. A snappier interface on slower PCs." }
    chkApplyMPO = @{ it = "Applica la scelta del menu sottostante per gli overlay multipiano. Disattivarli risolve spesso sfarfallii e scatti con più monitor."; en = "Applies the choice in the menu below for multiplane overlays. Turning them off often fixes flicker and stutter with multiple monitors." }
    chkVBS = @{ it = "Spegne la virtualizzazione di sicurezza di Windows. Più fotogrammi nei giochi, ma meno protezione contro il malware."; en = "Turns off Windows virtualization-based security. More frames in games, but less protection against malware." }
    chkMitigations = @{ it = "Toglie alcune protezioni contro gli exploit. Guadagno di prestazioni, ma il sistema diventa più esposto."; en = "Removes some protections against exploits. A performance gain, but the system becomes more exposed." }
    chkTelemetry = @{ it = "Blocca l'invio a Microsoft dei dati di utilizzo. Più privacy e meno attività in background."; en = "Stops usage data from being sent to Microsoft. More privacy and less background activity." }
    chkTelemetryTasks = @{ it = "Ferma le attività pianificate che raccolgono dati di utilizzo. Meno lavoro nascosto a computer acceso."; en = "Stops the scheduled tasks that collect usage data. Less hidden work while the computer is on." }
    chkActivityHistory = @{ it = "Windows smette di registrare cosa apri e quando. Più privacy."; en = "Windows stops recording what you open and when. More privacy." }
    chkLocationTracking = @{ it = "Spegne la localizzazione del dispositivo. Le app non sanno più dove ti trovi."; en = "Turns off device location. Apps no longer know where you are." }
    chkAdvertisingID = @{ it = "Toglie il codice che le app usano per mostrarti pubblicità mirata."; en = "Removes the code apps use to show you targeted ads." }
    chkTailoredExp = @{ it = "Microsoft smette di usare i tuoi dati per suggerimenti e pubblicità personalizzati."; en = "Microsoft stops using your data for personalized tips and ads." }
    chkFeedback = @{ it = "Niente più finestre che chiedono la tua opinione su Windows."; en = "No more pop-ups asking for your opinion on Windows." }
    chkErrorReporting = @{ it = "Gli errori dei programmi non vengono più inviati a Microsoft. Meno attività dopo un blocco."; en = "Program errors are no longer sent to Microsoft. Less activity after a crash." }
    chkInkingTyping = @{ it = "Windows smette di imparare da quello che scrivi e digiti. Più privacy."; en = "Windows stops learning from what you write and type. More privacy." }
    chkWiFiSense = @{ it = "Impedisce la condivisione automatica delle reti Wi-Fi e la connessione a hotspot sconosciuti."; en = "Prevents automatic Wi-Fi network sharing and connecting to unknown hotspots." }
    chkConsumerFeatures = @{ it = "Impedisce a Windows di installare da solo app e giochi promozionali."; en = "Stops Windows from installing promotional apps and games on its own." }
    chkSuggestedContent = @{ it = "Niente consigli e promozioni dentro Impostazioni e nel sistema."; en = "No tips and promotions inside Settings and around the system." }
    chkLockScreenAds = @{ it = "Toglie immagini a rotazione, consigli e pubblicità dalla schermata di blocco."; en = "Removes rotating images, tips and ads from the lock screen." }
    chkStartBing = @{ it = "La ricerca nel menu Start cerca solo sul computer, non su internet. Più veloce e più privata."; en = "Start menu search looks only on the computer, not the web. Faster and more private." }
    chkStartTracking = @{ it = "Windows smette di tenere l'elenco delle app più usate e dei documenti recenti."; en = "Windows stops keeping a list of your most used apps and recent documents." }
    chkFolderDiscovery = @{ it = "Esplora file non cerca più di indovinare il tipo di ogni cartella. Le cartelle grandi si aprono prima."; en = "File Explorer no longer tries to guess each folder's type. Large folders open faster." }
    chkWindowsAI = @{ it = "Spegne Copilot, Recall e le funzioni di intelligenza artificiale di Windows. Meno risorse usate e più privacy."; en = "Turns off Copilot, Recall and Windows AI features. Fewer resources used and more privacy." }
    chkEdgeDebloat = @{ it = "Edge non resta aperto in background e non precarica pagine. Meno memoria occupata."; en = "Edge no longer stays open in the background or preloads pages. Less memory used." }
    chkOneDriveRemove = @{ it = "Ferma la sincronizzazione di OneDrive. Utile se non usi il cloud di Microsoft."; en = "Stops OneDrive syncing. Useful if you do not use Microsoft's cloud." }
    chkOutlookNew = @{ it = "Impedisce il passaggio automatico al nuovo Outlook. Resti sulla versione che usi."; en = "Prevents the automatic switch to the new Outlook. You stay on the version you use." }
    chkServicesManual = @{ it = "I servizi poco usati partono solo quando servono. Avvio più leggero."; en = "Rarely used services start only when needed. A lighter startup." }
    chkDeliveryOpt = @{ it = "Il PC smette di condividere gli aggiornamenti con altri computer su internet. Risparmi banda."; en = "The PC stops sharing updates with other computers over the internet. Saves bandwidth." }
    chkBitLocker = @{ it = "Evita la cifratura automatica del disco. Disco un po' più veloce e niente chiave di ripristino da conservare."; en = "Avoids automatic drive encryption. A slightly faster disk and no recovery key to keep." }
    chkWPBT = @{ it = "Impedisce al firmware del produttore di installare programmi in Windows a tua insaputa."; en = "Prevents the manufacturer's firmware from installing programs into Windows without you knowing." }
    chkBackgroundApps = @{ it = "Le app dello Store non lavorano più quando sono chiuse. Meno batteria e memoria consumate."; en = "Store apps stop working while closed. Less battery and memory used." }
    chkTeredo = @{ it = "Spegne un vecchio tunnel di rete quasi mai usato. Può migliorare la connessione nei giochi online."; en = "Turns off an old, rarely used network tunnel. Can improve connections in online games." }
    chkRDPWarnings = @{ it = "Niente avvisi ripetuti quando apri connessioni Desktop remoto già note."; en = "No repeated warnings when opening known Remote Desktop connections." }
    chkRemoteAssistance = @{ it = "Impedisce ad altri di chiedere il controllo del tuo PC. Più sicurezza."; en = "Prevents others from requesting control of your PC. More security." }
    chkCompanionApps = @{ it = "Windows non scarica più app accessorie quando colleghi una periferica."; en = "Windows no longer downloads companion apps when you connect a device." }
    chkDriverUpdates = @{ it = "Windows Update non sostituisce più i driver che hai installato tu."; en = "Windows Update no longer replaces the drivers you installed yourself." }
    chkDarkTheme = @{ it = "Mette Windows e le app in tema scuro. Più riposante per gli occhi."; en = "Switches Windows and apps to dark mode. Easier on the eyes." }
    chkFileExt = @{ it = "Mostra .exe, .pdf e le altre estensioni. Riconosci subito i file sospetti."; en = "Shows .exe, .pdf and other extensions. You spot suspicious files right away." }
    chkHiddenFiles = @{ it = "Mostra file e cartelle nascosti in Esplora file."; en = "Shows hidden files and folders in File Explorer." }
    chkLongPaths = @{ it = "Permette percorsi di file molto lunghi. Evita errori con progetti e archivi profondi."; en = "Allows very long file paths. Avoids errors with deep projects and archives." }
    chkClassicMenu = @{ it = "Rimette il menu del tasto destro completo, senza passare da «Mostra altre opzioni»."; en = "Brings back the full right-click menu, without going through «Show more options»." }
    chkExplorerThisPC = @{ it = "Esplora file si apre su Questo PC, con dischi e cartelle in vista."; en = "File Explorer opens on This PC, with drives and folders in view." }
    chkRemove3D = @{ it = "Toglie la cartella Oggetti 3D, che quasi nessuno usa."; en = "Removes the 3D Objects folder, which almost nobody uses." }
    chkRecycleConfirm = @{ it = "Chiede conferma prima di spostare un file nel Cestino. Meno cancellazioni per sbaglio."; en = "Asks before moving a file to the Recycle Bin. Fewer accidental deletions." }
    chkMenuDelay = @{ it = "I menu si aprono all'istante, senza la piccola attesa predefinita."; en = "Menus open instantly, without the small default delay." }
    chkStartMorePins = @{ it = "Nel menu Start più spazio alle app fissate e meno ai consigli."; en = "More room for pinned apps in Start, less for recommendations." }
    chkStartHideRec = @{ it = "Nasconde la sezione Consigliati del menu Start. Start più pulito."; en = "Hides the Recommended section of the Start menu. A cleaner Start." }
    chkStartNoWeb = @{ it = "Toglie i siti web suggeriti dal menu Start."; en = "Removes suggested websites from the Start menu." }
    chkStartNoAccount = @{ it = "Niente avvisi sull'account Microsoft nel menu Start."; en = "No Microsoft account prompts in the Start menu." }
    chkTaskbarCenter = @{ it = "Tiene le icone della barra delle applicazioni al centro, come in Windows 11."; en = "Keeps taskbar icons centered, as in Windows 11." }
    chkTaskbarSearch = @{ it = "Toglie la casella di ricerca dalla barra. La ricerca resta disponibile dal tasto Windows."; en = "Removes the search box from the taskbar. Search is still available from the Windows key." }
    chkTaskbarTaskView = @{ it = "Toglie il pulsante Visualizzazione attività dalla barra."; en = "Removes the Task View button from the taskbar." }
    chkTaskbarWidgets = @{ it = "Toglie widget e notizie dalla barra. Meno memoria e meno distrazioni."; en = "Removes widgets and news from the taskbar. Less memory and fewer distractions." }
    chkTaskbarChat = @{ it = "Toglie l'icona di Chat e Teams dalla barra."; en = "Removes the Chat and Teams icon from the taskbar." }
    chkTaskbarEndTask = @{ it = "Aggiunge «Termina attività» al tasto destro sulla barra. Chiudi un programma bloccato senza Gestione attività."; en = "Adds «End task» to the taskbar right-click menu. Close a frozen program without Task Manager." }
    chkBatteryPct = @{ it = "Mostra la percentuale di carica accanto all'icona della batteria."; en = "Shows the charge percentage next to the battery icon." }
    chkSettingsHome = @{ it = "Impostazioni si apre direttamente sulle voci utili, senza la pagina iniziale promozionale."; en = "Settings opens straight to the useful sections, without the promotional home page." }
    chkWindowSnapping = @{ it = "Attiva l'affiancamento delle finestre trascinandole ai bordi dello schermo."; en = "Turns on window snapping when you drag windows to the screen edges." }
    chkMouseAccel = @{ it = "Il puntatore si muove sempre della stessa distanza. Mira più precisa e costante nei giochi."; en = "The pointer always moves the same distance. More precise, consistent aim in games." }
    chkNumLock = @{ it = "Il tastierino numerico è già attivo quando accendi il PC."; en = "The numeric keypad is already on when you start the PC." }
    chkStickyKeys = @{ it = "Niente finestra dei Tasti permanenti premendo più volte Maiusc, anche durante i giochi."; en = "No Sticky Keys prompt when pressing Shift repeatedly, even during games." }
    chkScrollbars = @{ it = "Le barre di scorrimento restano sempre visibili invece di comparire solo al passaggio."; en = "Scrollbars stay visible instead of appearing only on hover." }
    chkLockScreen = @{ it = "Salta la schermata di blocco e porta subito alla richiesta di accesso."; en = "Skips the lock screen and goes straight to sign-in." }
    chkLogonBlur = @{ it = "Toglie la sfocatura dallo sfondo di accesso. Immagine più nitida e accesso un filo più rapido."; en = "Removes the blur from the sign-in background. A sharper image and slightly faster sign-in." }
    chkBSODVerbose = @{ it = "La schermata blu mostra i dettagli dell'errore. Più facile capire la causa di un blocco."; en = "The blue screen shows the error details. Easier to find what caused a crash." }
    chkLogonVerbose = @{ it = "All'avvio e allo spegnimento vedi cosa sta facendo Windows. Utile per capire cosa lo rallenta."; en = "At startup and shutdown you see what Windows is doing. Helps find what slows it down." }
    chkApplyNetwork = @{ it = "Applica le impostazioni della pagina Rete. Senza questa spunta la pagina resta solo informativa."; en = "Applies the settings on the Network page. Without this box the page is informational only." }
    chkApplyDns = @{ it = "Usa i server DNS scelti nel menu. Pagine che si aprono più in fretta e, con alcuni servizi, meno pubblicità."; en = "Uses the DNS servers chosen in the menu. Pages open faster and, with some providers, fewer ads." }
    chkNetPowerSave = @{ it = "La scheda di rete non va più a risparmio energetico. Connessione più stabile e ping più regolare."; en = "The network card no longer goes into power saving. A steadier connection and more even ping." }
    chkDisableIPv6 = @{ it = "Spegne il protocollo IPv6. Utile solo se il tuo operatore non lo usa e hai problemi di connessione."; en = "Turns off IPv6. Useful only if your provider does not use it and you have connection issues." }
    chkStorageProfile = @{ it = "Applica le ottimizzazioni pensate per il tipo di disco scelto: SSD o disco meccanico."; en = "Applies the optimizations meant for the chosen drive type: SSD or hard disk." }
    chkDiskCleanup = @{ it = "Elimina file di sistema superflui e vecchie versioni degli aggiornamenti. Recupera spazio, a volte diversi GB."; en = "Deletes unneeded system files and old update versions. Recovers space, sometimes several GB." }
    chkSmartChkdsk = @{ it = "Controlla il disco al prossimo riavvio nel modo adatto a SSD o disco meccanico. Corregge errori del file system."; en = "Checks the disk at the next restart in the way that suits SSDs or hard disks. Fixes file system errors." }
    chkStorageSense = @{ it = "Windows non cancella più file da solo per fare spazio. Decidi tu cosa eliminare."; en = "Windows no longer deletes files on its own to make room. You decide what to remove." }
    chkReservedStorage = @{ it = "Libera lo spazio che Windows tiene da parte per gli aggiornamenti, circa 7 GB."; en = "Frees the space Windows keeps aside for updates, about 7 GB." }
    chkFastStartup = @{ it = "Ogni spegnimento diventa uno spegnimento completo. Risolve problemi di driver e dual boot."; en = "Every shutdown becomes a full shutdown. Fixes driver and dual-boot problems." }
    chkHibernation = @{ it = "Spegne l'ibernazione e libera sul disco C: uno spazio pari a gran parte della RAM."; en = "Turns off hibernation and frees space on C: roughly equal to most of your RAM." }
    chkS0Sleep = @{ it = "Con lo standby moderno il PC resta connesso mentre dorme: scarica aggiornamenti e si scalda in borsa. Spento, la rete si ferma durante lo standby."; en = "With modern standby the PC stays connected while asleep: it downloads updates and warms up in the bag. Off, networking stops during standby." }
    chkS3Sleep = @{ it = "Usa la sospensione classica al posto dello standby moderno: il PC dorme davvero. Se il BIOS non la supporta, la voce Sospendi sparisce: in quel caso ripristina questa voce."; en = "Uses classic sleep instead of modern standby: the PC really sleeps. If the BIOS doesn't support it, the Sleep option disappears: in that case reset this entry." }
    chkGpuTdr = @{ it = "Dà alla scheda video più tempo prima che Windows la riavvii. Meno schermi neri durante carichi pesanti."; en = "Gives the graphics card more time before Windows resets it. Fewer black screens under heavy load." }
    chkGpuMsi = @{ it = "Cambia il modo in cui la scheda video segnala al processore. Può ridurre la latenza."; en = "Changes how the graphics card signals the processor. Can reduce latency." }
    chkNvTelemetry = @{ it = "Ferma l'invio dei dati di utilizzo a NVIDIA. Meno processi in background."; en = "Stops usage data being sent to NVIDIA. Fewer background processes." }
    chkNvGfe = @{ it = "GeForce Experience non parte più da solo all'avvio. Avvio più leggero."; en = "GeForce Experience no longer starts by itself. A lighter startup." }
    chkNvPerfMode = @{ it = "La scheda NVIDIA resta alla massima frequenza. Prestazioni costanti, consumi più alti."; en = "Keeps the NVIDIA card at full clock speed. Steady performance, higher power draw." }
    chkNvUpdates = @{ it = "Il driver NVIDIA non controlla più da solo gli aggiornamenti."; en = "The NVIDIA driver no longer checks for updates on its own." }
    chkAmdUx = @{ it = "Ferma l'invio dei dati di utilizzo ad AMD."; en = "Stops usage data being sent to AMD." }
    chkAmdBloat = @{ it = "Evita che i programmi accessori AMD partano con Windows. Avvio più leggero."; en = "Keeps AMD companion programs from starting with Windows. A lighter startup." }
    chkIntelBloat = @{ it = "I servizi accessori della grafica Intel partono solo quando servono."; en = "Intel graphics companion services start only when needed." }
    chkSvcSysMain = @{ it = "Windows smette di precaricare in memoria le app che usi spesso. Utile su SSD veloci, dove non serve."; en = "Windows stops preloading your frequent apps into memory. Useful on fast SSDs, where it is not needed." }
    chkSvcDiag = @{ it = "Ferma i servizi che analizzano problemi e prestazioni in background."; en = "Stops the services that analyse problems and performance in the background." }
    chkSvcPca = @{ it = "Ferma il servizio che controlla la compatibilità dei vecchi programmi."; en = "Stops the service that checks old programs for compatibility." }
    chkSvcDiscovery = @{ it = "Il PC smette di cercare dispositivi sulla rete locale. Meno traffico, ma stampanti e TV di rete potrebbero non comparire."; en = "The PC stops searching for devices on the local network. Less traffic, but network printers and TVs may not show up." }
    chkSvcSensors = @{ it = "Ferma i servizi di sensori e posizione. Utile sui PC fissi, che non li hanno."; en = "Stops sensor and location services. Useful on desktops, which do not have them." }
    chkSvcSmartCard = @{ it = "Ferma i servizi per le smart card. Non servono se non usi lettori di tessere."; en = "Stops smart card services. Not needed if you do not use card readers." }
    chkSvcParental = @{ it = "Ferma controllo genitori e programma Insider. Non servono su un PC personale."; en = "Stops parental controls and the Insider program. Not needed on a personal PC." }
    chkSvcHyperV = @{ it = "Ferma i servizi delle macchine virtuali. Tienili se usi Hyper-V, WSL o l'emulatore Android."; en = "Stops virtual machine services. Keep them if you use Hyper-V, WSL or the Android emulator." }
    chkSvcPrint = @{ it = "Ferma il servizio di stampa. Da usare solo se non stampi mai da questo PC."; en = "Stops the print service. Only if you never print from this PC." }
    chkSvcSearch = @{ it = "Ferma l'indicizzazione dei file. Meno lavoro del disco, ma la ricerca diventa lenta."; en = "Stops file indexing. Less disk work, but search becomes slow." }
    chkSvcRemote = @{ it = "Ferma Desktop remoto e accesso remoto al registro. Più sicurezza se non ti colleghi da fuori."; en = "Stops Remote Desktop and remote registry access. More security if you never connect from outside." }
    chkSvcBiometric = @{ it = "Ferma impronta e riconoscimento del volto. Da evitare se accedi con Windows Hello."; en = "Stops fingerprint and face recognition. Avoid it if you sign in with Windows Hello." }
    chkSvcTouch = @{ it = "Ferma penna e tastiera virtuale. Da evitare su tablet e portatili touch."; en = "Stops pen and the on-screen keyboard. Avoid it on tablets and touch laptops." }
    chkTaskExtra = @{ it = "Spegne una ventina di attività automatiche di Microsoft che non servono. Meno lavoro nascosto."; en = "Turns off about twenty automatic Microsoft tasks you do not need. Less hidden work." }
    chkTaskMaint = @{ it = "Windows non avvia più la manutenzione automatica di notte. Il PC non si sveglia e non rallenta a sorpresa."; en = "Windows no longer runs automatic maintenance at night. The PC does not wake up or slow down unexpectedly." }
    chkTaskDefrag = @{ it = "Ferma l'ottimizzazione automatica dei dischi. Sugli SSD va poi fatta a mano dalla pagina Archiviazione."; en = "Stops automatic drive optimization. On SSDs it then has to be run by hand from the Storage page." }
    chkPrefetch = @{ it = "Windows smette di preparare in anticipo i file dei programmi. Meno scritture sugli SSD."; en = "Windows stops preparing program files in advance. Fewer writes on SSDs." }
    chkFth = @{ it = "Windows smette di applicare correzioni automatiche ai programmi che si bloccano. Comportamento più prevedibile."; en = "Windows stops applying automatic fixes to programs that crash. More predictable behaviour." }
    chkAppCompat = @{ it = "Spegne i controlli di compatibilità sui programmi. Avvio dei programmi un po' più rapido."; en = "Turns off compatibility checks on programs. Programs start slightly faster." }
    chkMemCompression = @{ it = "Windows smette di comprimere la memoria. Meno lavoro del processore, ma serve molta RAM."; en = "Windows stops compressing memory. Less processor work, but you need plenty of RAM." }
    chkWuNoReboot = @{ it = "Gli aggiornamenti non riavviano più il PC mentre lo usi."; en = "Updates no longer restart the PC while you are using it." }
    chkWuDefer = @{ it = "Le nuove versioni di Windows arrivano dopo un anno, quando sono già stabili. Le patch di sicurezza continuano ad arrivare."; en = "New Windows versions arrive after a year, once they are stable. Security patches keep coming." }
    chkWuNoStore = @{ it = "Le app dello Store non si aggiornano più da sole in background."; en = "Store apps no longer update themselves in the background." }
    chkBootQuiet = @{ it = "Avvio senza logo animato. Schermata più pulita e avvio un filo più rapido."; en = "Starts without the animated logo. A cleaner screen and a slightly faster boot." }
    chkBootMenu = @{ it = "Rimette il menu di avvio classico, che permette di entrare in modalità provvisoria con F8."; en = "Brings back the classic boot menu, which lets you enter Safe Mode with F8." }
    chkBootTimeout = @{ it = "Se hai più sistemi installati, il PC parte subito senza aspettare nel menu di scelta."; en = "If several systems are installed, the PC starts right away without waiting in the choice menu." }
    chkBootDynTick = @{ it = "Il processore tiene un ritmo di sistema costante. Su alcuni PC abbassa la latenza, su altri no: va provato."; en = "The processor keeps a constant system tick. On some PCs it lowers latency, on others it does not: test it." }
    chkBootTsc = @{ it = "Rende più precisa la misura del tempo tra i core del processore. Può migliorare la fluidità: va provato."; en = "Makes timekeeping across processor cores more precise. Can improve smoothness: test it." }
    chkAppxBloat = @{ it = "Rimuove app preinstallate come notizie, meteo, mappe e Skype. Più spazio e menu Start più ordinato."; en = "Removes preinstalled apps such as news, weather, maps and Skype. More space and a tidier Start menu." }
    chkAppxXbox = @{ it = "Rimuove le app Xbox e l'overlay di gioco. Da evitare se usi Game Pass."; en = "Removes Xbox apps and the game overlay. Avoid it if you use Game Pass." }
    chkAppxProvision = @{ it = "Le app rimosse non ricompaiono quando si crea un nuovo utente."; en = "Removed apps do not come back when a new user is created." }
    chkSecSmartScreen = @{ it = "Spegne il controllo dei file scaricati. Nessun avviso all'apertura, ma nessuna protezione da file pericolosi."; en = "Turns off the check on downloaded files. No warnings when opening them, but no protection from dangerous files." }
    chkSecSpectre = @{ it = "Toglie le protezioni contro alcune falle dei processori. Più prestazioni, soprattutto sulle CPU vecchie, ma meno sicurezza."; en = "Removes protections against some processor flaws. More performance, especially on older CPUs, but less security." }
    chkSecDefenderIdle = @{ it = "L'antivirus fa le scansioni solo a computer fermo e senza appesantirlo. La protezione in tempo reale resta attiva."; en = "The antivirus scans only when the computer is idle and without weighing it down. Real-time protection stays on." }
    chkRestorePoint = @{ it = "Crea un punto di ripristino prima di applicare. Se qualcosa non va, torni indietro da Ripristino configurazione di sistema."; en = "Creates a restore point before applying. If something goes wrong, you can go back with System Restore." }
    chkAmdUlps = @{ it = "Impedisce alla scheda AMD di spegnersi quando è a riposo. Frequenze pronte e niente micro-scatti al risveglio, consumi un po' più alti."; en = "Stops the AMD card from powering down when idle. Clocks stay ready and no micro-stutter on wake-up, slightly higher power draw." }
    chkMenuSleep = @{ it = "Mostra o nasconde Sospendi nel menu di spegnimento di Start. Il cambio vale subito."; en = "Shows or hides Sleep in the Start power menu. The change applies immediately." }
    chkMenuHibernate = @{ it = "Mostra o nasconde Iberna nel menu di spegnimento di Start. Se l'ibernazione era spenta, viene riattivata."; en = "Shows or hides Hibernate in the Start power menu. If hibernation was off, it is turned back on." }
    chkNvP2 = @{ it = "Il driver non abbassa più le frequenze della memoria quando parte un programma CUDA. Rendering e calcolo più veloci."; en = "The driver stops lowering memory clocks when a CUDA program starts. Faster rendering and compute." }
    chkNvDrsPower = @{ it = "La scheda resta alle frequenze alte invece di rallentare tra un fotogramma e l'altro. Meno cali di FPS."; en = "The card stays at high clocks instead of slowing between frames. Fewer FPS drops." }
    chkNvLowLatency = @{ it = "Come «Attiva» nel Pannello di controllo NVIDIA: il processore prepara un solo fotogramma in anticipo. Più compatibile di «Ultra», che con alcuni giochi e con G-SYNC crea scatti."; en = "Like «On» in the NVIDIA Control Panel: the processor prepares just one frame ahead. More compatible than «Ultra», which stutters with some games and with G-SYNC." }
    chkNvThreaded = @{ it = "I giochi OpenGL distribuiscono il lavoro del driver su più core."; en = "OpenGL games spread the driver's work over several cores." }
    chkNvTexPerf = @{ it = "Il filtro delle texture privilegia la velocità: qualche FPS in più, differenza visiva minima."; en = "Texture filtering favors speed: a few more FPS, minimal visual difference." }
    chkNvAniso = @{ it = "Il filtro anisotropico usa meno campioni dove non si vede la differenza."; en = "Anisotropic filtering takes fewer samples where the difference doesn't show." }
    chkNvShaderCache = @{ it = "Il driver non cancella gli shader compilati: meno scatti quando un gioco carica aree nuove."; en = "The driver keeps compiled shaders: fewer stutters when a game loads new areas." }
    chkNvDisplayPower = @{ it = "Il driver non abbassa la luminosità dello schermo per risparmiare energia."; en = "The driver doesn't dim the screen to save power." }
    chkNvHdcp = @{ it = "Toglie la protezione dei contenuti: meno lavoro per la scheda, ma Netflix e simili non vanno in alta risoluzione."; en = "Removes content protection: less work for the card, but Netflix and similar won't play in high resolution." }
    chkNvPreempt = @{ it = "La scheda finisce un lavoro prima di passare al successivo. Può ridurre la latenza, su alcuni PC causa blocchi."; en = "The card finishes a job before switching to the next. It can reduce latency; on some PCs it causes hangs." }
    chkNvDynPstate = @{ it = "La scheda non scende mai di frequenza. Massima reattività, più calore e consumo anche a riposo."; en = "The card never lowers its clocks. Maximum responsiveness, more heat and power even at idle." }
    chkNvLatency = @{ it = "Riduce le attese interne del driver usate per risparmiare energia. Effetto variabile: provalo e misura."; en = "Cuts the driver's internal waits used to save power. The effect varies: try it and measure." }
    chkAmdAntiLag = @{ it = "Il processore non corre avanti rispetto alla scheda video. Comandi più immediati nei giochi."; en = "The processor doesn't run ahead of the graphics card. Snappier controls in games." }
    chkAmdShaderCache = @{ it = "Gli shader compilati restano sempre salvati: meno scatti ai caricamenti."; en = "Compiled shaders are always kept: fewer stutters on loading." }
    chkAmdTexPerf = @{ it = "Il filtro delle texture privilegia la velocità, con differenze minime a vista."; en = "Texture filtering favors speed, with barely visible differences." }
    chkAmdTess = @{ it = "Il driver limita la tassellatura esagerata di alcuni giochi. FPS più alti nelle scene pesanti."; en = "The driver caps some games' excessive tessellation. Higher FPS in heavy scenes." }
    chkAmdFlipQueue = @{ it = "Un solo fotogramma in coda verso lo schermo. Meno ritardo tra mouse e immagine."; en = "Only one frame queued to the screen. Less delay between mouse and image." }
    chkAmdNoFrtc = @{ it = "Toglie il tetto agli FPS impostato dal driver."; en = "Removes the FPS cap set by the driver." }
    chkAmdStutter = @{ it = "La memoria video non entra in risparmio tra un fotogramma e l'altro. Tempi dei fotogrammi più regolari."; en = "Video memory doesn't power down between frames. Steadier frame times." }
    chkAmdAspm = @{ it = "Il collegamento PCIe della scheda resta sempre attivo. Niente micro-ritardi al risveglio."; en = "The card's PCIe link stays always active. No micro-delays on wake-up." }
    chkAmdPowerGating = @{ it = "Le unità della scheda non vengono spente a riposo. Più reattiva, consuma e scalda di più."; en = "The card's units aren't powered off at idle. More responsive, more power and heat." }
    chkAmdDma = @{ it = "Cambia il modo in cui la scheda copia i dati. Su alcune schede riduce gli scatti, su altre li peggiora."; en = "Changes how the card copies data. On some cards it reduces stutter, on others it worsens it." }
    chkAmdPreempt = @{ it = "La scheda finisce un calcolo prima di passare al successivo. Da provare: su alcuni PC causa blocchi."; en = "The card finishes a compute job before the next one. Worth testing: on some PCs it causes hangs." }
    chkNvNoAnsel = @{ it = "Spegne Ansel, l'overlay fotografico di NVIDIA che resta caricato in ogni gioco."; en = "Turns off Ansel, NVIDIA's photo overlay that stays loaded in every game." }
    chkIntelTelemetry = @{ it = "Disattiva il programma di miglioramento e il resoconto d'uso installati con l'assistente driver Intel. Il driver grafico non ne ha bisogno."; en = "Disables the improvement program and usage report installed with Intel's driver assistant. The graphics driver does not need them." }
    chkIntelGfxPower = @{ it = "Nel piano energetico, con l'alimentazione collegata, la grafica integrata Intel lavora alla frequenza piena invece di risparmiare. A batteria non cambia nulla."; en = "In the power plan, while plugged in, Intel integrated graphics run at full clock instead of saving power. Nothing changes on battery." }
    chkIntelDpst = @{ it = "Sui portatili Intel lo schermo abbassa luminosità e contrasto in base a ciò che mostra: spento, i colori restano costanti. Su alcuni modelli il driver lo riaccende al riavvio."; en = "On Intel laptops the screen lowers brightness and contrast based on what it shows: off, colors stay constant. On some models the driver turns it back on at restart." }
    chkCpuIntelBoostPol = @{ it = "Con l'alimentazione collegata, il turbo dei processori Intel sale senza il limite della politica del piano energetico. A batteria resta com'era."; en = "While plugged in, Intel processor turbo climbs without the power plan's policy limit. On battery it stays as before." }
    chkCpuIntelHybrid = @{ it = "Solo processori con core P ed E (dalla 12ª generazione): i thread vanno ai core P quando possibile. Utile nei giochi; i core E restano disponibili quando il carico cresce."; en = "Only processors with P and E cores (12th gen onward): threads go to the P-cores when possible. Useful in games; the E-cores stay available as load grows." }
    chkCpuAmdParking = @{ it = "Con l'alimentazione collegata tutti i core restano pronti invece di essere parcheggiati. Non si attiva sui Ryzen X3D a due chiplet, dove il parcheggio serve ai giochi."; en = "While plugged in, all cores stay ready instead of being parked. Not available on dual-chiplet Ryzen X3D, where parking helps games." }
    chkCpuIdleOff = @{ it = "Il processore non entra mai negli stati di riposo: latenza minima, ma consumi e temperature sempre alti anche a PC fermo. Solo su un fisso ben raffreddato, con l'alimentazione collegata."; en = "The processor never enters idle states: minimum latency, but power draw and temperatures stay high even at rest. Only on a well-cooled desktop, while plugged in." }
    chkAdvUtc = @{ it = "Windows legge l'ora del BIOS come UTC, come fa Linux: con il doppio avvio l'orologio non salta più di un'ora a ogni cambio di sistema."; en = "Windows reads the BIOS time as UTC, like Linux: with dual boot the clock no longer jumps an hour each time you switch systems." }
    chkAdvRazer = @{ it = "Blocca i co-installer dei driver e la cartella in cui Razer Synapse si copia quando colleghi una periferica. Blocca anche i co-installer di altri produttori."; en = "Blocks driver co-installers and the folder Razer Synapse copies itself into when you plug in a device. It also blocks other vendors' co-installers." }
    chkAdvLogi = @{ it = "Chiude l'assistente download Logitech e gli impedisce di reinstallarsi a ogni avvio."; en = "Closes the Logitech download assistant and stops it from reinstalling at every startup." }
    chkIPv4Pref = @{ it = "IPv6 resta attivo, ma Windows prova prima IPv4. Utile con reti o router che gestiscono male IPv6."; en = "IPv6 stays on, but Windows tries IPv4 first. Useful with networks or routers that handle IPv6 poorly." }
    chkDiskNoSleep = @{ it = "Con l'alimentazione collegata dischi, collegamento SATA e SSD NVMe non entrano mai in risparmio: niente attese al risveglio. A batteria resta tutto com'era."; en = "While plugged in, disks, the SATA link and NVMe SSDs never enter power saving: no wake-up delays. On battery everything stays as before." }
}

