        'M:pd_ultimate' = "Plan oculto de Windows: sin ahorro de energía, latencia mínima."
        'M:pd_bitsum' = "Plan de Bitsum (Process Lasso): rendimiento de CPU constante."
        'M:pd_high' = "Plan estándar de Windows de alto rendimiento."
        'M:pd_balanced' = "Plan predeterminado de Windows. Úsalo para volver atrás."
