        'H:chkKernelDpc' = "Réduit les délais de traitement des cartes et périphériques. Aide contre les micro-saccades et les craquements audio."
        'H:chkTimer' = "Rend les minuteries du système plus précises. Des temps de réponse plus réguliers en jeu."
        'H:chkPowerThrottling' = "Empêche Windows de ralentir les programmes en arrière-plan pour économiser l'énergie. Performances constantes, consommation un peu plus élevée."
        'H:chkUSBSuspend' = "Garde les ports USB toujours actifs. Souris, claviers et cartes son ne décrochent plus et répondent sans retard."
        'H:chkNtfsPerf' = "Le disque ne note plus chaque lecture de fichier et utilise plus de mémoire pour les données système. Moins d'écritures, accès plus rapides."
        'H:chkRamTweak' = "Regroupe les services de Windows selon la RAM installée. Moins de processus ouverts et une mémoire mieux utilisée."
        'H:chkGameMode' = "Active le Mode Jeu : Windows met en retrait mises à jour et tâches pendant que vous jouez."
        'H:chkFSO' = "Fait tourner les jeux plein écran en mode exclusif. Peut réduire la latence d'entrée dans certains titres."
        'H:chkGameDVR' = "Coupe l'enregistrement en arrière-plan de la Xbox Game Bar. Libère des ressources et fait gagner quelques images."
        'H:chkHAGS' = "Laisse la carte graphique gérer elle-même sa mémoire. Latence plus faible sur les cartes récentes."
        'H:chkVisualFX' = "Réduit les animations et effets visuels de Windows. Interface plus réactive sur les PC modestes."
        'H:chkApplyMPO' = "Applique le choix du menu ci-dessous pour les superpositions multiplans. Les désactiver corrige souvent scintillements et saccades avec plusieurs écrans."
        'H:chkVBS' = "Coupe la sécurité basée sur la virtualisation. Plus d'images en jeu, mais moins de protection contre les logiciels malveillants."
        'H:chkMitigations' = "Retire certaines protections contre les exploits. Gain de performances, mais le système est plus exposé."
        'H:chkTelemetry' = "Bloque l'envoi des données d'utilisation à Microsoft. Plus de confidentialité et moins d'activité en arrière-plan."
        'H:chkTelemetryTasks' = "Arrête les tâches planifiées qui collectent des données d'utilisation. Moins de travail caché."
        'H:chkActivityHistory' = "Windows n'enregistre plus ce que vous ouvrez et quand. Plus de confidentialité."
        'H:chkLocationTracking' = "Coupe la localisation de l'appareil. Les applications ne savent plus où vous êtes."
        'H:chkAdvertisingID' = "Retire l'identifiant que les applications utilisent pour vous montrer des publicités ciblées."
        'H:chkTailoredExp' = "Microsoft n'utilise plus vos données pour des conseils et publicités personnalisés."
        'H:chkFeedback' = "Plus de fenêtres qui demandent votre avis sur Windows."
        'H:chkErrorReporting' = "Les erreurs des programmes ne sont plus envoyées à Microsoft. Moins d'activité après un plantage."
        'H:chkInkingTyping' = "Windows n'apprend plus de ce que vous écrivez et tapez. Plus de confidentialité."
        'H:chkWiFiSense' = "Empêche le partage automatique des réseaux Wi-Fi et la connexion à des points d'accès inconnus."
        'H:chkConsumerFeatures' = "Empêche Windows d'installer de lui-même des applications et jeux promotionnels."
        'H:chkSuggestedContent' = "Plus de conseils ni de promotions dans Paramètres et dans le système."
        'H:chkLockScreenAds' = "Retire images changeantes, conseils et publicités de l'écran de verrouillage."
        'H:chkStartBing' = "La recherche du menu Démarrer cherche seulement sur l'ordinateur, pas sur internet. Plus rapide et plus privée."
        'H:chkStartTracking' = "Windows ne tient plus la liste des applications les plus utilisées et des documents récents."
        'H:chkFolderDiscovery' = "L'Explorateur n'essaie plus de deviner le type de chaque dossier. Les gros dossiers s'ouvrent plus vite."
        'H:chkWindowsAI' = "Coupe Copilot, Recall et les fonctions d'IA de Windows. Moins de ressources utilisées et plus de confidentialité."
        'H:chkEdgeDebloat' = "Edge ne reste plus ouvert en arrière-plan et ne précharge plus de pages. Moins de mémoire occupée."
        'H:chkOneDriveRemove' = "Arrête la synchronisation de OneDrive. Utile si vous n'utilisez pas le cloud de Microsoft."
        'H:chkOutlookNew' = "Empêche le passage automatique au nouvel Outlook. Vous gardez la version que vous utilisez."
        'H:chkServicesManual' = "Les services peu utilisés démarrent seulement quand il le faut. Démarrage plus léger."
        'H:chkDeliveryOpt' = "Le PC ne partage plus les mises à jour avec d'autres ordinateurs sur internet. Économise de la bande passante."
        'H:chkBitLocker' = "Évite le chiffrement automatique du disque. Disque un peu plus rapide et aucune clé de récupération à conserver."
        'H:chkWPBT' = "Empêche le firmware du fabricant d'installer des programmes dans Windows à votre insu."
        'H:chkBackgroundApps' = "Les applications du Store ne travaillent plus une fois fermées. Moins de batterie et de mémoire consommées."
        'H:chkTeredo' = "Coupe un ancien tunnel réseau presque jamais utilisé. Peut améliorer la connexion dans les jeux en ligne."
        'H:chkRDPWarnings' = "Plus d'avertissements répétés à l'ouverture de connexions Bureau à distance connues."
        'H:chkRemoteAssistance' = "Empêche d'autres personnes de demander le contrôle de votre PC. Plus de sécurité."
        'H:chkCompanionApps' = "Windows ne télécharge plus d'applications compagnons quand vous branchez un appareil."
        'H:chkDriverUpdates' = "Windows Update ne remplace plus les pilotes que vous avez installés vous-même."
        'H:chkDarkTheme' = "Passe Windows et les applications en thème sombre. Plus reposant pour les yeux."
        'H:chkFileExt' = "Affiche .exe, .pdf et les autres extensions. Vous repérez tout de suite les fichiers suspects."
        'H:chkHiddenFiles' = "Affiche les fichiers et dossiers cachés dans l'Explorateur."
        'H:chkLongPaths' = "Autorise les chemins de fichiers très longs. Évite les erreurs avec les projets et archives profonds."
        'H:chkClassicMenu' = "Rétablit le menu complet du clic droit, sans passer par « Afficher d'autres options »."
        'H:chkExplorerThisPC' = "L'Explorateur s'ouvre sur Ce PC, avec disques et dossiers en vue."
        'H:chkRemove3D' = "Retire le dossier Objets 3D, que presque personne n'utilise."
        'H:chkRecycleConfirm' = "Demande confirmation avant d'envoyer un fichier à la Corbeille. Moins de suppressions par erreur."
        'H:chkMenuDelay' = "Les menus s'ouvrent instantanément, sans le petit délai par défaut."
        'H:chkStartMorePins' = "Dans le menu Démarrer, plus de place pour les applications épinglées et moins pour les conseils."
        'H:chkStartHideRec' = "Masque la section Recommandé du menu Démarrer. Un Démarrer plus propre."
        'H:chkStartNoWeb' = "Retire les sites web suggérés du menu Démarrer."
        'H:chkStartNoAccount' = "Plus d'avertissements du compte Microsoft dans le menu Démarrer."
        'H:chkTaskbarCenter' = "Garde les icônes de la barre des tâches au centre, comme dans Windows 11."
        'H:chkTaskbarSearch' = "Retire la zone de recherche de la barre. La recherche reste accessible avec la touche Windows."
        'H:chkTaskbarTaskView' = "Retire le bouton Vue des tâches de la barre."
        'H:chkTaskbarWidgets' = "Retire widgets et actualités de la barre. Moins de mémoire et moins de distractions."
        'H:chkTaskbarChat' = "Retire l'icône Conversation et Teams de la barre."
        'H:chkTaskbarEndTask' = "Ajoute « Fin de tâche » au clic droit de la barre. Fermez un programme bloqué sans le Gestionnaire des tâches."
        'H:chkBatteryPct' = "Affiche le pourcentage de charge à côté de l'icône de batterie."
        'H:chkSettingsHome' = "Paramètres s'ouvre directement sur les sections utiles, sans la page d'accueil promotionnelle."
        'H:chkWindowSnapping' = "Active l'ancrage des fenêtres quand vous les faites glisser vers les bords de l'écran."
        'H:chkMouseAccel' = "Le pointeur parcourt toujours la même distance. Visée plus précise et régulière en jeu."
        'H:chkNumLock' = "Le pavé numérique est déjà actif à l'allumage du PC."
        'H:chkStickyKeys' = "Plus de fenêtre des touches rémanentes en appuyant plusieurs fois sur Maj, même en jeu."
        'H:chkScrollbars' = "Les barres de défilement restent visibles au lieu d'apparaître seulement au survol."
        'H:chkLockScreen' = "Saute l'écran de verrouillage et mène directement à la connexion."
        'H:chkLogonBlur' = "Retire le flou du fond de connexion. Image plus nette et connexion un peu plus rapide."
        'H:chkBSODVerbose' = "L'écran bleu affiche les détails de l'erreur. Plus facile de trouver la cause d'un plantage."
        'H:chkLogonVerbose' = "Au démarrage et à l'arrêt, vous voyez ce que fait Windows. Aide à trouver ce qui le ralentit."
        'H:chkApplyNetwork' = "Applique les réglages de la page Réseau. Sans cette case, la page reste informative."
        'H:chkApplyDns' = "Utilise les serveurs DNS choisis dans le menu. Pages plus rapides à s'ouvrir et, avec certains services, moins de publicité."
        'H:chkNetPowerSave' = "La carte réseau ne passe plus en économie d'énergie. Connexion plus stable et ping plus régulier."
        'H:chkDisableIPv6' = "Coupe IPv6. Utile seulement si votre fournisseur ne l'utilise pas et que vous avez des problèmes de connexion."
        'H:chkStorageProfile' = "Applique les optimisations prévues pour le type de disque choisi : SSD ou disque mécanique."
        'H:chkDiskCleanup' = "Supprime les fichiers système inutiles et les anciennes versions des mises à jour. Récupère de l'espace, parfois plusieurs Go."
        'H:chkSmartChkdsk' = "Vérifie le disque au prochain redémarrage de la façon adaptée au SSD ou au disque mécanique. Corrige les erreurs du système de fichiers."
        'H:chkStorageSense' = "Windows ne supprime plus de fichiers de lui-même pour faire de la place. C'est vous qui décidez."
        'H:chkReservedStorage' = "Libère l'espace que Windows garde de côté pour les mises à jour, environ 7 Go."
        'H:chkFastStartup' = "Chaque arrêt devient un arrêt complet. Résout des problèmes de pilotes et de double démarrage."
        'H:chkHibernation' = "Coupe la mise en veille prolongée et libère sur C: un espace proche d'une grande partie de la RAM."
        'H:chkS0Sleep' = "En veille, le PC ne reste pas connecté à internet. Il consomme moins et ne se réveille pas tout seul."
        'H:chkS3Sleep' = "Utilise la veille classique au lieu de la veille moderne. Le portable ne chauffe pas dans le sac."
        'H:chkGpuTdr' = "Donne plus de temps à la carte graphique avant que Windows ne la réinitialise. Moins d'écrans noirs sous forte charge."
        'H:chkGpuMsi' = "Change la façon dont la carte graphique signale le processeur. Peut réduire la latence."
        'H:chkNvTelemetry' = "Arrête l'envoi des données d'utilisation à NVIDIA. Moins de processus en arrière-plan."
        'H:chkNvGfe' = "GeForce Experience ne démarre plus tout seul. Démarrage plus léger."
        'H:chkNvPerfMode' = "Garde la carte NVIDIA à sa fréquence maximale. Performances constantes, consommation plus élevée."
        'H:chkNvUpdates' = "Le pilote NVIDIA ne cherche plus de lui-même les mises à jour."
        'H:chkAmdUx' = "Arrête l'envoi des données d'utilisation à AMD."
        'H:chkAmdBloat' = "Empêche les programmes annexes AMD de démarrer avec Windows. Démarrage plus léger."
        'H:chkIntelBloat' = "Les services annexes des graphismes Intel démarrent seulement quand il le faut."
        'H:chkSvcSysMain' = "Windows ne précharge plus en mémoire les applications que vous utilisez souvent. Utile sur les SSD rapides, où ce n'est pas nécessaire."
        'H:chkSvcDiag' = "Arrête les services qui analysent problèmes et performances en arrière-plan."
        'H:chkSvcPca' = "Arrête le service qui vérifie la compatibilité des anciens programmes."
        'H:chkSvcDiscovery' = "Le PC ne cherche plus d'appareils sur le réseau local. Moins de trafic, mais imprimantes et TV réseau peuvent ne plus apparaître."
        'H:chkSvcSensors' = "Arrête les services de capteurs et de localisation. Utile sur les PC fixes, qui n'en ont pas."
        'H:chkSvcSmartCard' = "Arrête les services de cartes à puce. Inutiles si vous n'utilisez pas de lecteur de cartes."
        'H:chkSvcParental' = "Arrête le contrôle parental et le programme Insider. Inutiles sur un PC personnel."
        'H:chkSvcHyperV' = "Arrête les services des machines virtuelles. Gardez-les si vous utilisez Hyper-V, WSL ou l'émulateur Android."
        'H:chkSvcPrint' = "Arrête le service d'impression. Seulement si vous n'imprimez jamais depuis ce PC."
        'H:chkSvcSearch' = "Arrête l'indexation des fichiers. Moins de travail pour le disque, mais la recherche devient lente."
        'H:chkSvcRemote' = "Arrête le Bureau à distance et l'accès distant au registre. Plus de sécurité si vous ne vous connectez jamais de l'extérieur."
        'H:chkSvcBiometric' = "Arrête l'empreinte et la reconnaissance faciale. À éviter si vous vous connectez avec Windows Hello."
        'H:chkSvcTouch' = "Arrête le stylet et le clavier tactile. À éviter sur tablettes et portables tactiles."
        'H:chkTaskExtra' = "Coupe une vingtaine de tâches automatiques de Microsoft inutiles. Moins de travail caché."
        'H:chkTaskMaint' = "Windows ne lance plus la maintenance automatique la nuit. Le PC ne se réveille pas et ne ralentit pas par surprise."
        'H:chkTaskDefrag' = "Arrête l'optimisation automatique des lecteurs. Sur SSD, il faudra la lancer à la main depuis la page Stockage."
        'H:chkPrefetch' = "Windows ne prépare plus à l'avance les fichiers des programmes. Moins d'écritures sur les SSD."
        'H:chkFth' = "Windows n'applique plus de corrections automatiques aux programmes qui plantent. Comportement plus prévisible."
        'H:chkAppCompat' = "Coupe les contrôles de compatibilité des programmes. Les programmes démarrent un peu plus vite."
        'H:chkMemCompression' = "Windows ne compresse plus la mémoire. Moins de travail pour le processeur, mais il faut beaucoup de RAM."
        'H:chkWuNoReboot' = "Les mises à jour ne redémarrent plus le PC pendant que vous l'utilisez."
        'H:chkWuDefer' = "Les nouvelles versions de Windows arrivent un an plus tard, une fois stables. Les correctifs de sécurité continuent d'arriver."
        'H:chkWuNoStore' = "Les applications du Store ne se mettent plus à jour seules en arrière-plan."
        'H:chkBootQuiet' = "Démarre sans le logo animé. Écran plus sobre et démarrage un peu plus rapide."
        'H:chkBootMenu' = "Rétablit le menu de démarrage classique, qui permet d'entrer en mode sans échec avec F8."
        'H:chkBootTimeout' = "Si plusieurs systèmes sont installés, le PC démarre tout de suite sans attendre dans le menu de choix."
        'H:chkBootDynTick' = "Le processeur garde un rythme système constant. Sur certains PC la latence baisse, sur d'autres non : à tester."
        'H:chkBootTsc' = "Rend la mesure du temps entre les cœurs du processeur plus précise. Peut améliorer la fluidité : à tester."
        'H:chkAppxBloat' = "Supprime des applications préinstallées comme actualités, météo, cartes et Skype. Plus d'espace et un Démarrer mieux rangé."
        'H:chkAppxXbox' = "Supprime les applications Xbox et la superposition de jeu. À éviter si vous utilisez le Game Pass."
        'H:chkAppxProvision' = "Les applications supprimées ne reviennent pas à la création d'un nouvel utilisateur."
        'H:chkSecSmartScreen' = "Coupe le contrôle des fichiers téléchargés. Plus d'avertissement à l'ouverture, mais plus de protection contre les fichiers dangereux."
