        'H:chkSecDefenderIdle' = "L'antivirus analyse seulement quand l'ordinateur est au repos, sans l'alourdir. La protection en temps réel reste active."
        'H:chkRestorePoint' = "Crée un point de restauration avant d'appliquer. En cas de problème, vous revenez en arrière avec la Restauration du système."
