        'H:chkReservedStorage' = "Zwalnia miejsce, które Windows rezerwuje na aktualizacje, około 7 GB."
        'H:chkFastStartup' = "Każde zamknięcie staje się pełnym wyłączeniem. Rozwiązuje problemy ze sterownikami i dwoma systemami."
        'H:chkHibernation' = "Wyłącza hibernację i zwalnia na C: miejsce zbliżone do dużej części RAM."
        'H:chkS0Sleep' = "W uśpieniu komputer nie jest połączony z internetem. Zużywa mniej i nie budzi się sam."
        'H:chkS3Sleep' = "Używa klasycznego uśpienia zamiast nowoczesnego. Laptop nie nagrzewa się w plecaku."
        'H:chkGpuTdr' = "Daje karcie graficznej więcej czasu, zanim Windows ją zresetuje. Mniej czarnych ekranów pod dużym obciążeniem."
        'H:chkGpuMsi' = "Zmienia sposób, w jaki karta graficzna sygnalizuje procesorowi. Może zmniejszyć opóźnienia."
        'H:chkNvTelemetry' = "Zatrzymuje wysyłanie danych o użytkowaniu do NVIDIA. Mniej procesów w tle."
        'H:chkNvGfe' = "GeForce Experience nie uruchamia się już sam. Lżejszy start."
        'H:chkNvPerfMode' = "Utrzymuje kartę NVIDIA na pełnym taktowaniu. Stała wydajność, większy pobór prądu."
        'H:chkNvUpdates' = "Sterownik NVIDIA nie sprawdza już sam aktualizacji."
        'H:chkAmdUx' = "Zatrzymuje wysyłanie danych o użytkowaniu do AMD."
        'H:chkAmdBloat' = "Nie pozwala dodatkowym programom AMD startować z Windows. Lżejszy start."
