        'H:chkMMCSS' = "Dă prioritate jocurilor și sunetului când computerul e încărcat. Mai puține sacadări și sunet mai curat."
        'H:chkPriority' = "Oferă mai mult timp de procesor ferestrei pe care o folosești. Programul din prim-plan răspunde mai repede."
        'H:chkKernelMem' = "Păstrează nucleul Windows în memorie în loc să-l mute pe disc. Sistem mai vioi cu multă RAM."
        'H:chkKernelDpc' = "Reduce întârzierile în servirea plăcilor și dispozitivelor. Ajută împotriva micro-sacadărilor și pocniturilor audio."
        'H:chkTimer' = "Face temporizatoarele sistemului mai precise. Timpi de răspuns mai constanți în jocuri."
        'H:chkPowerThrottling' = "Împiedică Windows să încetinească programele din fundal pentru a economisi energie. Performanță constantă, consum puțin mai mare."
        'H:chkUSBSuspend' = "Ține porturile USB mereu active. Mouse-urile, tastaturile și plăcile de sunet nu se mai deconectează și nu mai răspund cu întârziere."
        'H:chkNtfsPerf' = "Discul nu mai notează fiecare citire de fișier și folosește mai multă memorie pentru datele de sistem. Mai puține scrieri, acces mai rapid."
        'H:chkRamTweak' = "Grupează serviciile Windows după memoria RAM instalată. Mai puține procese și memorie folosită mai bine."
        'H:chkGameMode' = "Pornește Modul joc: Windows amână actualizările și activitățile cât timp joci."
        'H:chkFSO' = "Rulează jocurile pe ecran complet în mod exclusiv. Poate reduce întârzierea la comenzi în unele titluri."
        'H:chkGameDVR' = "Oprește înregistrarea în fundal a Xbox Game Bar. Eliberează resurse și câștigă câteva cadre."
        'H:chkHAGS' = "Lasă placa video să-și gestioneze singură memoria. Latență mai mică pe plăcile recente."
        'H:chkVisualFX' = "Reduce animațiile și efectele vizuale din Windows. Interfață mai rapidă pe PC-urile modeste."
        'H:chkApplyMPO' = "Aplică alegerea din meniul de dedesubt pentru suprapunerile multiplan. Dezactivarea rezolvă adesea pâlpâiri și sacadări cu mai multe monitoare."
        'H:chkVBS' = "Oprește securitatea bazată pe virtualizare. Mai multe cadre în jocuri, dar mai puțină protecție împotriva programelor malware."
        'H:chkMitigations' = "Elimină unele protecții împotriva exploit-urilor. Câștig de performanță, dar sistemul e mai expus."
        'H:chkTelemetry' = "Blochează trimiterea datelor de utilizare către Microsoft. Mai multă confidențialitate și mai puțină activitate în fundal."
        'H:chkTelemetryTasks' = "Oprește activitățile programate care colectează date de utilizare. Mai puțină muncă ascunsă."
        'H:chkActivityHistory' = "Windows nu mai înregistrează ce deschizi și când. Mai multă confidențialitate."
        'H:chkLocationTracking' = "Oprește localizarea dispozitivului. Aplicațiile nu mai știu unde te afli."
        'H:chkAdvertisingID' = "Elimină codul folosit de aplicații pentru a-ți arăta reclame țintite."
        'H:chkTailoredExp' = "Microsoft nu mai folosește datele tale pentru sfaturi și reclame personalizate."
        'H:chkFeedback' = "Gata cu ferestrele care îți cer părerea despre Windows."
        'H:chkErrorReporting' = "Erorile programelor nu mai sunt trimise către Microsoft. Mai puțină activitate după un blocaj."
        'H:chkInkingTyping' = "Windows nu mai învață din ce scrii și tastezi. Mai multă confidențialitate."
        'H:chkWiFiSense' = "Împiedică partajarea automată a rețelelor Wi-Fi și conectarea la hotspot-uri necunoscute."
        'H:chkConsumerFeatures' = "Împiedică Windows să instaleze singur aplicații și jocuri promoționale."
        'H:chkSuggestedContent' = "Fără sfaturi și promoții în Setări și în sistem."
        'H:chkLockScreenAds' = "Elimină imaginile care se schimbă, sfaturile și reclamele de pe ecranul de blocare."
        'H:chkStartBing' = "Căutarea din meniul Start caută doar pe computer, nu pe internet. Mai rapidă și mai privată."
        'H:chkStartTracking' = "Windows nu mai ține lista aplicațiilor folosite des și a documentelor recente."
        'H:chkFolderDiscovery' = "Explorer nu mai încearcă să ghicească tipul fiecărui folder. Folderele mari se deschid mai repede."
        'H:chkWindowsAI' = "Oprește Copilot, Recall și funcțiile AI din Windows. Mai puține resurse folosite și mai multă confidențialitate."
        'H:chkEdgeDebloat' = "Edge nu mai rămâne deschis în fundal și nu mai preîncarcă pagini. Mai puțină memorie ocupată."
        'H:chkOneDriveRemove' = "Oprește sincronizarea OneDrive. Util dacă nu folosești cloudul Microsoft."
        'H:chkOutlookNew' = "Împiedică trecerea automată la noul Outlook. Rămâi la versiunea pe care o folosești."
        'H:chkServicesManual' = "Serviciile rar folosite pornesc doar când e nevoie. Pornire mai ușoară."
        'H:chkDeliveryOpt' = "PC-ul nu mai partajează actualizări cu alte computere pe internet. Economisești lățime de bandă."
        'H:chkBitLocker' = "Evită criptarea automată a discului. Disc puțin mai rapid și nicio cheie de recuperare de păstrat."
        'H:chkWPBT' = "Împiedică firmware-ul producătorului să instaleze programe în Windows fără știrea ta."
        'H:chkBackgroundApps' = "Aplicațiile din Store nu mai lucrează când sunt închise. Mai puțină baterie și memorie consumate."
        'H:chkTeredo' = "Oprește un tunel de rețea vechi, aproape nefolosit. Poate îmbunătăți conexiunea în jocurile online."
        'H:chkRDPWarnings' = "Fără avertismente repetate la deschiderea conexiunilor Desktop la distanță cunoscute."
        'H:chkRemoteAssistance' = "Împiedică pe alții să ceară controlul PC-ului tău. Mai multă siguranță."
        'H:chkCompanionApps' = "Windows nu mai descarcă aplicații însoțitoare când conectezi un dispozitiv."
        'H:chkDriverUpdates' = "Windows Update nu mai înlocuiește driverele instalate de tine."
        'H:chkDarkTheme' = "Trece Windows și aplicațiile pe tema întunecată. Mai odihnitor pentru ochi."
        'H:chkFileExt' = "Afișează .exe, .pdf și celelalte extensii. Recunoști imediat fișierele suspecte."
