        'H:chkNvP2' = "Драйвер перестаёт снижать частоту памяти при запуске программ CUDA. Быстрее рендеринг и вычисления."
        'H:chkNvDrsPower' = "Карта держит высокие частоты, а не снижает их между кадрами. Меньше просадок FPS."
        'H:chkNvThreaded' = "Игры на OpenGL распределяют работу драйвера по нескольким ядрам."
        'H:chkNvTexPerf' = "Фильтрация текстур в пользу скорости: немного больше FPS, разница почти не видна."
        'H:chkNvAniso' = "Анизотропная фильтрация берёт меньше выборок там, где разница незаметна."
        'H:chkNvShaderCache' = "Драйвер хранит скомпилированные шейдеры: меньше фризов при загрузке новых зон."
        'H:chkNvDisplayPower' = "Драйвер не затемняет экран ради экономии энергии."
        'H:chkNvHdcp' = "Отключает защиту контента: меньше нагрузки на карту, но Netflix и подобные не будут показывать в высоком разрешении."
        'H:chkNvPreempt' = "Карта завершает задачу перед переходом к следующей. Может снизить задержку; на некоторых ПК вызывает зависания."
        'H:chkNvDynPstate' = "Карта никогда не снижает частоты. Максимальная отзывчивость, больше нагрев и потребление даже в простое."
        'H:chkNvLatency' = "Сокращает внутренние ожидания драйвера для экономии энергии. Эффект разный: проверьте и измерьте."
        'H:chkAmdAntiLag' = "Процессор не забегает вперёд видеокарты. Управление в играх отзывчивее."
        'H:chkAmdShaderCache' = "Скомпилированные шейдеры хранятся всегда: меньше фризов при загрузке."
        'H:chkAmdTexPerf' = "Фильтрация текстур в пользу скорости, разница едва заметна."
        'H:chkAmdTess' = "Драйвер ограничивает избыточную тесселяцию в некоторых играх. Больше FPS в тяжёлых сценах."
        'H:chkAmdFlipQueue' = "Только один кадр в очереди на экран. Меньше задержка между мышью и изображением."
        'H:chkAmdNoFrtc' = "Снимает ограничение FPS, заданное драйвером."
        'H:chkAmdStutter' = "Видеопамять не отключается между кадрами. Время кадра стабильнее."
        'H:chkAmdAspm' = "Канал PCIe карты всегда активен. Нет микрозадержек при пробуждении."
        'H:chkAmdPowerGating' = "Блоки карты не отключаются в простое. Отзывчивее, но больше потребление и нагрев."
        'H:chkAmdDma' = "Меняет способ копирования данных картой. На одних картах уменьшает фризы, на других усиливает."
        'H:chkAmdPreempt' = "Карта завершает вычисление перед следующим. Стоит проверить: на некоторых ПК вызывает зависания."
        'H:chkNvLowLatency' = "Как «Вкл» в Панели управления NVIDIA: процессор готовит только один кадр вперёд. Совместимее, чем «Ультра», которая даёт рывки в некоторых играх и с G-SYNC."
        'H:chkNvNoAnsel' = "Отключает Ansel — фотооверлей NVIDIA, загружаемый в каждой игре."
        'H:chkIntelTelemetry' = "Отключает программу улучшения и отчёт об использовании, устанавливаемые помощником драйверов Intel. Графическому драйверу они не нужны."
        'H:chkIntelGfxPower' = "В схеме питания от сети встроенная графика Intel работает на полной частоте, а не экономит. От батареи ничего не меняется."
        'H:chkIntelDpst' = "На ноутбуках Intel экран снижает яркость и контраст в зависимости от изображения: при отключении цвета постоянны. На некоторых моделях драйвер включает это снова после перезагрузки."
        'H:chkCpuIntelBoostPol' = "От сети турбо процессоров Intel растёт без ограничения политики схемы питания. От батареи всё как раньше."
        'H:chkCpuIntelHybrid' = "Только процессоры с ядрами P и E (с 12-го поколения): потоки по возможности идут на P-ядра. Полезно в играх; E-ядра доступны при росте нагрузки."
        'H:chkCpuAmdParking' = "От сети все ядра остаются готовыми, а не паркуются. Недоступно на Ryzen X3D с двумя чиплетами, где парковка помогает играм."
        'H:chkCpuIdleOff' = "Процессор никогда не переходит в состояния простоя: минимальная задержка, но потребление и температура высокие даже в покое. Только на хорошо охлаждаемом ПК от сети."
        'H:chkAdvUtc' = "Windows читает время BIOS как UTC, как Linux: при двойной загрузке часы больше не сдвигаются на час при смене системы."
        'H:chkAdvRazer' = "Блокирует соустановщики драйверов и папку, куда Razer Synapse копирует себя при подключении устройства. Также блокирует соустановщики других производителей."
        'H:chkAdvLogi' = "Закрывает помощник загрузки Logitech и не даёт ему переустанавливаться при каждом запуске."
        'H:chkIPv4Pref' = "IPv6 остаётся включённым, но Windows сначала пробует IPv4. Полезно с сетями или роутерами, плохо работающими с IPv6."
        'H:chkDiskNoSleep' = "От сети диски, канал SATA и NVMe SSD никогда не переходят в энергосбережение: без задержек пробуждения. От батареи всё как раньше."
        'M:pwRecBtn' = "Рекомендуемые значения"
        'M:pwDefBtn' = "Вернуть значения Windows"
        'M:pwAskRec' = "Установить рекомендуемые значения в текущей схеме? Изменения вступят в силу сразу."
        'M:pwAskDef' = "Вернуть в текущей схеме значения Windows по умолчанию? Изменения вступят в силу сразу."
        'M:svcMissing' = "Нет на этом ПК"
    }
}

foreach ($lang in $script:Tr.Keys) {
    foreach ($entry in $script:Tr[$lang].GetEnumerator()) {
        $kind, $name = $entry.Key -split ':', 2
        $table = switch ($kind) { 'L' { $script:Loc } 'M' { $script:Msg } 'H' { $script:Tips } }
        if ($table.ContainsKey($name)) { $table[$name][$lang] = $entry.Value }
    }
}
